const lead = $('Parse CSV').item.json;
const r = $input.item.json;
const status = Number(r.statusCode || 0);
const base = {company: lead.company, domain: lead.domain_slug, source: lead.source};
if (status !== 200) return {json: {...base, status: 'unreachable', score: 0, note: 'HTTP ' + (status || 'error')}};
const html = String(r.data || '');
const pick = re => { const m = html.match(re); return m ? m[1].trim() : ''; };
const desc = pick(/<meta name="description" content="([^"]*)"/i);
const email = pick(/mailto:([^"]+)"/i), phone = pick(/<span class="tel">([^<]*)</i), industry = pick(/Industry:\s*([^<]+)</i);
const emp = desc.match(/(\d+)\s*(?:employees|people|accountants|dentists|team members)/i);
const size = emp ? Number(emp[1]) : null;
const tech = (desc.match(/WordPress|Shopify|Wix|Squarespace/i) || [''])[0];
const signals = [];
if (/hiring/i.test(desc)) signals.push('hiring');
if (/Series [A-D]|funded|raised/i.test(desc)) signals.push('funded');
let score = 20; const why = [];
if (size >= 10 && size <= 200) { score += 25; why.push('size 10-200'); } else if (size >= 3) { score += 10; why.push('small team'); }
if (email) { score += 20; why.push('public e-mail'); }
if (phone) { score += 10; why.push('phone'); }
if (signals.length) { score += 15; why.push(signals.join('+')); }
if (/Logistics|Healthcare|Finance/i.test(industry)) { score += 10; why.push('target industry'); }
return {json: {...base, status: 'enriched', industry, size: size ?? '', tech, contact_email: email, phone, signals: signals.join('+'), score, why: why.join('; '), note: ''}};

const q = v => '"' + String(v ?? '').replace(/"/g, '""').replace(/[\r\n]+/g, ' ') + '"';

const COLS = ["domain", "company", "status", "score", "industry", "size", "tech", "contact_email", "phone", "signals", "why", "source", "first_seen", "last_enriched", "note"];
const parse = txt => { const rows = []; let row = [], cur = '', inq = false;
  for (let i = 0; i < txt.length; i++) { const c = txt[i];
    if (inq) { if (c === '"' && txt[i + 1] === '"') { cur += '"'; i++; } else if (c === '"') inq = false; else cur += c; }
    else if (c === '"') inq = true; else if (c === ',') { row.push(cur); cur = ''; } else if (c === '\n') { row.push(cur); rows.push(row); row = []; cur = ''; } else if (c !== '\r') cur += c; }
  return rows; };
const crm = {};
const it = $input.first();
if (it.binary && it.binary.data) {
  const rows = parse((await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8')); const h = rows.shift();
  rows.filter(r => r.length === h.length).forEach(r => { const o = {}; h.forEach((k, i) => o[k] = r[i]); crm[o.domain] = o; });
}
const today = new Date().toISOString().slice(0, 10);
let added = 0, updated = 0;
for (const l of $('Collect all leads').first().json.leads) {
  const old = crm[l.domain];
  if (old) { updated++; crm[l.domain] = {...old, ...l, first_seen: old.first_seen, last_enriched: today}; }
  else { added++; crm[l.domain] = {...l, first_seen: today, last_enriched: today}; }
}
const all = Object.values(crm).sort((a, b) => Number(b.score) - Number(a.score));
const csv = COLS.join(',') + '\n' + all.map(o => COLS.map(k => q(o[k])).join(',')).join('\n') + '\n';
const hot = all.filter(o => Number(o.score) >= Number($('Config').first().json.hot_score));
const bin = await this.helpers.prepareBinaryData(Buffer.from(csv, 'utf8'), 'crm.csv', 'text/csv');
return [{json: {added, updated, total: all.length, hot: hot.map(o => `${o.company} (${o.score})`), unreachable: all.filter(o => o.status === 'unreachable').length}, binary: {data: bin}}];
